let data = $("person").last().json;

let rawName = data.Nome || "";
let rawPhone = data.Telefone?.[0]?.value || "";

// Função para normalizar o nome
function normalizeName(name) {
    name = name.trim().toLowerCase();
    return name.charAt(0).toUpperCase() + name.slice(1);
}

function normalizePhone(phone) {
    // 1. Remove todos os caracteres que não são números
    let digits = phone.replace(/\D/g, "");

    // 2. Se começar com '55', remove para processar o número
    if (digits.startsWith("55")) {
        digits = digits.slice(2);
    }

    // 3. Verifica se tem 10 ou 11 dígitos após remoção do 55
    if (digits.length !== 10 && digits.length !== 11) {
        throw new Error("Número inválido: deve ter 10 ou 11 dígitos após remover o código do país.");
    }

    // 4. Se tem 10 dígitos, assume que está faltando o '9' e adiciona após o DDD
    if (digits.length === 10) {
        digits = digits.slice(0, 2) + '9' + digits.slice(2);
    }

    // 5. Se tem 11 dígitos mas o terceiro dígito não é '9', adiciona (corrige números mal formatados)
    if (digits.length === 11 && digits[2] !== '9') {
        digits = digits.slice(0, 2) + '9' + digits.slice(2, 10);
    }

    // 6. Número final deve ter 11 dígitos (2 DDD + 9 + 8 números)
    if (digits.length !== 11) {
        throw new Error("Número inválido após normalização.");
    }

    // 7. Adiciona o código do país '55'
    return "55" + digits;
}

let name = normalizeName(rawName);
let phone = normalizePhone(rawPhone);

let crm_type = "person"
let crm_type_id = data.ID

return { name, phone, crm_type, crm_type_id };

