let data = $("loop").last().json;
let data_deal = $("deal1").last().json.item;

let rawName = data.nome || "";
let rawPhone = data.numero || "";

// Função para normalizar o nome
function normalizeName(name) {
    name = name.trim().toLowerCase();
    return name.charAt(0).toUpperCase() + name.slice(1);
}

// Função para normalizar o telefone
function normalizePhone(phone) {
    let digits = phone.replace(/\D/g, "");

    if (digits.startsWith("55")) {
        digits = digits.slice(2);
    }

    if (digits.length !== 10 && digits.length !== 11) {
        throw new Error("Número inválido: deve ter 10 ou 11 dígitos após remover o código do país.");
